CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'reader' CHECK(role IN ('reader','admin')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS devotionals (id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL UNIQUE,title TEXT NOT NULL,theme TEXT NOT NULL DEFAULT '',bible_text TEXT NOT NULL DEFAULT '',memory_verse TEXT NOT NULL DEFAULT '',reflection TEXT NOT NULL DEFAULT '',think_about TEXT NOT NULL DEFAULT '',prayer TEXT NOT NULL DEFAULT '',challenge TEXT NOT NULL DEFAULT '',sample INTEGER NOT NULL DEFAULT 0,published INTEGER NOT NULL DEFAULT 0,source_pages TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS monthly_themes (month INTEGER PRIMARY KEY CHECK(month BETWEEN 1 AND 12),title TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscription_plans (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,months INTEGER NOT NULL UNIQUE CHECK(months>0),amount_kobo INTEGER NOT NULL CHECK(amount_kobo>0),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL UNIQUE REFERENCES users(id),plan_id INTEGER NOT NULL REFERENCES subscription_plans(id),started_at TEXT NOT NULL,expires_at TEXT NOT NULL,renewal_mode TEXT NOT NULL CHECK(renewal_mode IN ('manual','automatic')),cancel_at_period_end INTEGER NOT NULL DEFAULT 0,is_demo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),subscription_id INTEGER NOT NULL REFERENCES subscriptions(id),plan_id INTEGER NOT NULL REFERENCES subscription_plans(id),plan_name TEXT NOT NULL,amount_kobo INTEGER NOT NULL CHECK(amount_kobo>0),reference TEXT NOT NULL UNIQUE,provider TEXT NOT NULL CHECK(provider IN ('demo')),status TEXT NOT NULL CHECK(status='succeeded'),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reading_progress (user_id INTEGER NOT NULL REFERENCES users(id),devotional_id INTEGER NOT NULL REFERENCES devotionals(id),completed_at TEXT NOT NULL,PRIMARY KEY(user_id,devotional_id));
CREATE TABLE IF NOT EXISTS bookmarks (user_id INTEGER NOT NULL REFERENCES users(id),devotional_id INTEGER NOT NULL REFERENCES devotionals(id),created_at TEXT NOT NULL,PRIMARY KEY(user_id,devotional_id));
CREATE TABLE IF NOT EXISTS journal_entries (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),devotional_id INTEGER REFERENCES devotionals(id),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hardcover_inquiries (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL,message TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','reviewed')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,admin_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_journals_owner ON journal_entries(user_id);
CREATE INDEX IF NOT EXISTS idx_payments_user ON payments(user_id);
CREATE INDEX IF NOT EXISTS idx_progress_entry ON reading_progress(devotional_id);
